func TestStopTwiceDoesNotPanic(t *testing.T) {
	s := store.New(func() time.Time { return t0 })
	d := NewDispatcher(s, slog.New(slog.NewTextHandler(io.Discard, nil)), func() time.Time { return t0 })
	d.Stop()
	defer func() {
		if p := recover(); p != nil {
			t.Fatalf("second Stop panicked: %v", p)
		}
	}()
	d.Stop()
}

