import "testing"

func TestParseBearerWithoutToken(t *testing.T) {
	for _, h := range []string{"Bearer", "Bearer ", "Bearerx"} {
		func() {
			defer func() {
				if p := recover(); p != nil {
					t.Fatalf("parseBearer(%q) panicked: %v", h, p)
				}
			}()
			if tok, ok := parseBearer(h); ok {
				t.Errorf("parseBearer(%q) = %q, true; want false", h, tok)
			}
		}()
	}
	if tok, ok := parseBearer("Bearer abc"); !ok || tok != "abc" {
		t.Errorf("parseBearer(valid) = %q, %v", tok, ok)
	}
}

